html:
{%- macro emp(e) -%}{{ (frappe.db.get_value("Employee", e, "employee_name") or e) if e else "" }}{%- endmacro -%}
{%- macro usr(u) -%}{{ (frappe.db.get_value("User", u, "full_name") or u) if u else "" }}{%- endmacro -%}
{%- macro dt(v) -%}{{ frappe.format(v, {"fieldtype": "Date"}) if v else "" }}{%- endmacro -%}
{%- macro box(on) -%}<span class="cb">{% if on %}X{% endif %}</span>{%- endmacro -%}
{%- macro txt(v) -%}{{ (v or "") | e | replace("\n", "<br>") }}{%- endmacro -%}
{%- set e = frappe.db.get_value("Employee", doc.employee, ["designation", "department", "date_of_joining"], as_dict=True) or {} -%}
{%- set req = frappe.db.get_value("Training Requirement", doc.training_requirement, ["verification_method", "document_number", "document_revision", "high_hazard"], as_dict=True) or {} -%}
{%- set rec = frappe.db.get_value("Training Record", doc.training_record, ["training_date", "document_revision", "trainer_name", "external_provider"], as_dict=True) if doc.training_record else None -%}
{%- set authorized = frappe.db.get_value("Qualified Trainer Course", {"parent": doc.evaluator, "parenttype": "Qualified Trainer", "training_requirement": doc.training_requirement, "status": "Active"}, "name") if doc.evaluator else None -%}
<style>
	.trn { font-family: Arial, Helvetica, sans-serif; color: #000; font-size: 11px; }
	.print-format .trn td, .print-format .trn th, .trn td, .trn th { padding: 3px 6px !important; vertical-align: top; line-height: 1.25; }
	.trn table { width: 100%; border-collapse: collapse; table-layout: fixed; }
	.trn .hdr td { vertical-align: middle; font-size: 9px; }
	.trn h1 { font-size: 22px; font-weight: bold; text-align: center; margin: 6px 0 4px 0; padding-bottom: 3px; border-bottom: 1px solid #555; }
	.trn .frame { border: 2px solid #000; margin-top: 8px; }
	.trn .info td { border: 1px solid #000; height: 22px; vertical-align: middle; }
	.trn .info .lbl { text-align: right; font-weight: bold; width: 19%; }
	.trn .sec { font-weight: bold; }
	.trn .text td.tb { border-bottom: 1px solid #000; height: 62px; }
	.trn .text td.tb.last { border-bottom: none; }
	.trn .body { margin-top: 2px; }
	.trn .cb { display: inline-block; width: 10px; height: 10px; border: 1px solid #000; line-height: 10px; text-align: center; font-size: 9px; font-weight: bold; vertical-align: middle; margin-left: 6px; }
	.trn .r { text-align: right; }
	.trn .c { text-align: center; }
	.trn .rule { border-top: 2px solid #000; }
	.trn .grid th { border: 1px solid #000; background: #f2f2f2; font-weight: bold; text-align: center; vertical-align: middle; }
	.trn .grid td { border: 1px solid #000; }
	.trn .stamp { margin-top: 6px; font-size: 9px; color: #333; }
	.trn .void { border: 2px solid #b42318; color: #b42318; font-weight: bold; text-align: center; padding: 4px; margin-top: 6px; font-size: 12px; }
	.trn .foot { margin-top: 6px; font-size: 9px; page-break-inside: avoid; }
	.trn .foot td { vertical-align: top; }
</style>
<div class="trn">
	<table class="hdr">
		<tr>
			<td style="width:28%">355 Gus Hipp Blvd.<br>Rockledge, FL 32955</td>
			<td style="width:44%; text-align:center"><img src="{{ frappe.utils.get_url('/assets/hse/images/psif_logo.jpg') }}" style="height:52px"></td>
			<td style="width:28%; text-align:right">Tel: (321) 636-0085<br><b>www.psifla.com</b></td>
		</tr>
	</table>
	<h1>{{ _("TRN-704 Competency Evaluation / OJT Checklist") }}</h1>
	{% if doc.docstatus == 2 %}<div class="void">{{ _("CANCELLED: this record is void") }}</div>{% elif doc.docstatus == 0 and True %}<div class="void">{{ _("DRAFT: not yet submitted") }}</div>{% endif %}

	<table class="frame info">
		<tr>
			<td class="lbl">{{ _("EVALUATION NO.:") }}</td><td>{{ doc.name }}</td>
			<td class="lbl">{{ _("DATE:") }}</td><td>{{ dt(doc.evaluation_date) }}</td>
		</tr>
		<tr>
			<td class="lbl">{{ _("EMPLOYEE:") }}</td><td>{{ doc.employee_name or "" }} <span style="font-size:9px; color:#555">({{ doc.employee }})</span></td>
			<td class="lbl">{{ _("DEPARTMENT:") }}</td><td>{{ e.department or "" }}</td>
		</tr>
		<tr>
			<td class="lbl">{{ _("POSITION:") }}</td><td>{{ e.designation or "" }}</td>
			<td class="lbl">{{ _("HIRE DATE:") }}</td><td>{{ dt(e.date_of_joining) }}</td>
		</tr>
		<tr>
			<td class="lbl">{{ _("COURSE:") }}</td>
			<td colspan="3"><b>{{ doc.training_requirement }}</b> {{ doc.course_title or "" }}{% if req.high_hazard %} <span style="font-size:9px">({{ _("high-hazard") }})</span>{% endif %}</td>
		</tr>
		<tr>
			<td class="lbl">{{ _("DOC. / REV.:") }}</td><td>{{ req.document_number or "" }}{% if (rec and rec.document_revision) or req.document_revision %} {{ _("Rev.") }} {{ (rec and rec.document_revision) or req.document_revision }}{% endif %}</td>
			<td class="lbl">{{ _("VERIFICATION:") }}</td><td>{{ _(req.verification_method) if req.verification_method else "" }}</td>
		</tr>
		<tr>
			<td class="lbl">{{ _("BASIS:") }}</td>
			<td colspan="3">{{ _("Training") }} {{ box(doc.basis == "Training") }} &nbsp;&nbsp;&nbsp; {{ _("Prior experience") }} {{ box(doc.basis == "Prior Experience") }}</td>
		</tr>
		{% if rec %}
		<tr>
			<td class="lbl">{{ _("TRAINING REC.:") }}</td>
			<td colspan="3">{{ doc.training_record }}, {{ dt(rec.training_date) }}{% if rec.trainer_name or rec.external_provider %}, {{ _("trainer") }} {{ rec.trainer_name or rec.external_provider }}{% endif %}</td>
		</tr>
		{% endif %}
		{% if doc.basis == "Prior Experience" %}
		<tr>
			<td class="lbl">{{ _("EVIDENCE:") }}</td><td colspan="3">{{ (doc.evidence or "").split("/")[-1] if doc.evidence else _("None attached") }}</td>
		</tr>
		{% endif %}
	</table>

	<table class="frame grid">
		<thead>
			<tr>
				<th style="width:5%">#</th>
				<th style="width:28%">{{ _("Task / Skill") }}</th>
				<th style="width:29%">{{ _("Acceptance Criteria") }}</th>
				<th style="width:7%">{{ _("Pass") }}</th>
				<th style="width:7%">{{ _("Fail") }}</th>
				<th style="width:6%">{{ _("N/A") }}</th>
				<th>{{ _("Comments") }}</th>
			</tr>
		</thead>
		<tbody>
			{% for row in doc.checklist %}
			<tr>
				<td class="c">{{ loop.index }}</td>
				<td>{{ row.item or "" }}</td>
				<td>{{ txt(row.criteria) }}</td>
				<td class="c">{{ box(row.result == "Pass") }}</td>
				<td class="c">{{ box(row.result == "Fail") }}</td>
				<td class="c">{{ box(row.result == "N/A") }}</td>
				<td>{{ txt(row.comments) }}</td>
			</tr>
			{% else %}
			<tr><td colspan="7" class="c" style="height:40px; vertical-align:middle">{{ _("No checklist items recorded.") }}</td></tr>
			{% endfor %}
		</tbody>
	</table>

	<table class="frame">
		<tr>
			<td style="width:34%; vertical-align:middle"><span class="sec">{{ _("OVERALL RESULT:") }}</span></td>
			<td class="r" style="width:28%">{{ _("PASS (Qualified)") }} {{ box(doc.result == "Pass") }}</td>
			<td class="r" style="padding-right:30px !important">{{ _("FAIL (retrain, re-evaluate)") }} {{ box(doc.result == "Fail") }}</td>
		</tr>
		<tr><td colspan="3" style="height:40px">{{ _("Comments:") }} {{ txt(doc.comments) }}</td></tr>
		<tr>
			<td colspan="2" class="rule" style="height:26px; vertical-align:middle">{{ _("Evaluated By:") }} {{ doc.evaluator_name or emp(doc.evaluator) }}
				<span style="font-size:9px">({{ _("Qualified Trainer for this course") if authorized else _("not on the Qualified Trainer register for this course") }})</span></td>
			<td class="rule" style="vertical-align:middle">{{ _("Date:") }} {{ dt(doc.evaluation_date) }}</td>
		</tr>
	</table>

	<div class="stamp">{{ _("Recorded electronically under the evaluator's login; signatures are not required (TRN-700 §4.13).") }}
		{% if doc.docstatus == 1 %}{{ _("Submitted by") }} {{ usr(doc.modified_by) }}, {{ frappe.format(doc.modified, {"fieldtype": "Datetime"}) }}.{% endif %}</div>

	<table class="foot">
		<tr>
			<td style="width:30%"></td>
			<td style="width:40%; text-align:center">{{ _("TRN-704 Competency Evaluation / OJT Checklist") }}<br><i>{{ _("Printed copies of this form are uncontrolled") }}</i></td>
			<td style="width:30%; text-align:right">{{ _("Rev. 0: 10/26") }}</td>
		</tr>
	</table>
</div>
